import{c as t,Q as o,j as r,m as s}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Insight Report — Loop Engineering 教學 × Harness 自我稽核實戰","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-20-loop-engineering-harness-insight.md","filePath":"research/reports/2026-07-20-loop-engineering-harness-insight.md","lastUpdated":1785909234000}'),a={name:"research/reports/2026-07-20-loop-engineering-harness-insight.md"};function n(d,e,i,l,c,g){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="insight-report-—-loop-engineering-教學-×-harness-自我稽核實戰" tabindex="-1">Insight Report — Loop Engineering 教學 × Harness 自我稽核實戰 <a class="header-anchor" href="#insight-report-—-loop-engineering-教學-×-harness-自我稽核實戰" aria-label="Permalink to &quot;Insight Report — Loop Engineering 教學 × Harness 自我稽核實戰&quot;">​</a></h1><blockquote><p><strong>日期</strong>：2026-07-20 · <strong>分支</strong>：<code>claude/loop-engineering-harness-ni06xa</code> · <strong>性質</strong>：一次教學驅動的 harness 自我稽核+優化實戰 <strong>觸發</strong>：使用者以 ThariqS「Teacher SKILL」gist 學 Loop Engineering，載體=實戰優化本 harness。 <strong>一句話結論</strong>：這個 workspace 不缺器官，缺的是<strong>循環系統</strong>——它的<strong>寫入路徑（write path）世界級，讀取路徑（read path）是斷的</strong>。要成為智能體，該補的不是更多組件，是把「已存在的資料送到需要它的那一刻」的 retrieval 迴圈。</p></blockquote><h2 id="_1-本次交付-已完成並驗證" tabindex="-1">1. 本次交付（已完成並驗證） <a class="header-anchor" href="#_1-本次交付-已完成並驗證" aria-label="Permalink to &quot;1. 本次交付（已完成並驗證）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>交付</th><th>內容</th><th>驗證</th><th>commit</th></tr></thead><tbody><tr><td>新 SKILL <code>deep-understanding</code></td><td><code>/teach</code> mastery-gated 教學迴圈（= 本場教學用的方法自舉）</td><td>frontmatter 7 欄、觸發</td><td>d3709ae</td></tr><tr><td>3-agent 跨 context 稽核</td><td>L1 規則 / SKILL 路由 / 散文-vs-gate 三維，12 缺口 backlog</td><td>2 agent 獨立收斂 terraform 缺口</td><td>—</td></tr><tr><td><strong>P0#1</strong> IaC 破壞性 gate</td><td>block-dangerous.sh 焊 terraform/tofu/terragrunt destroy + auto-approve</td><td><strong>Fable 抓到 8 繞過→修→21/21 自驗</strong></td><td>b22bbf4→(fix)</td></tr><tr><td><strong>P0#2</strong> branch-guard 誠實化</td><td>假宣稱「保護 main」→ 誠實化 + 真 main 警示（fail-open）</td><td>語法+fail-open</td><td>5242797</td></tr><tr><td>Phase 1 概念地圖</td><td><code>CONCEPT-MAP-v4.md</code>：7 概念×最新/實現/gap（6-agent 合成）</td><td>Fable 抽驗 artifact</td><td>bd40c67</td></tr><tr><td>P1/P2 批次</td><td>N 斷鏈修復、Handoff 誠實化、audit 消歧、/goal 自清</td><td>byte 帶內、指針解析</td><td>23167b6</td></tr><tr><td>/goal 事實校正</td><td>誤判「無原生 /goal」→ 官方 docs 證實原生（v2.1.139+ Haiku validator）</td><td>claude-code-guide + Fable</td><td>f5c857f</td></tr></tbody></table><h2 id="_2-本次最重要的一課-fable-抓到我抓不到的-harness-論點的活體驗證" tabindex="-1">2. 本次最重要的一課：Fable 抓到我抓不到的（harness 論點的活體驗證） <a class="header-anchor" href="#_2-本次最重要的一課-fable-抓到我抓不到的-harness-論點的活體驗證" aria-label="Permalink to &quot;2. 本次最重要的一課：Fable 抓到我抓不到的（harness 論點的活體驗證）&quot;">​</a></h2><p>我對 P0#1 自報「13/13 fixture 通過、破壞性全擋」。<strong>Fable frontier 終審（異模型、fresh context、對抗立場）裁定 NOT-FAITHFUL</strong>——用<strong>最自然的 terraform 寫法</strong>繞過我的 gate：<code>(cd envs/prod &amp;&amp; terraform destroy)</code>、<code>terraform destroy;</code>、<code>$(terraform destroy)</code>、<code>terraform &quot;destroy&quot;</code>、<code>-auto-approve=true</code>。</p><ul><li><strong>根因</strong>：我的 destroy 終止符只容忍空白/行末，而<strong>同一個檔的 <code>is_dangerous_rm</code> 早就用終止符類 <code>T=&#39;[[:space:])|;&amp;]&#39;</code> 解過</strong>——我沒重用既有慣例就回歸了。</li><li><strong>這驗證了三條 harness 鐵律</strong>：① <code>unverified_success</code>（自報成功=中間態）② 「壞 oracle 比沒有更糟／gate 須行使實際執行路徑非 proxy 子集」——我的 fixture 是 proxy 子集，給了假信心 ③ 「對抗審查優先異模型」——只有不同模型的對抗立場抓得到我的盲點。</li><li><strong>自我 oracle 的盲點形狀 = 作者的盲點形狀</strong>：我寫的 fixture 測不到我想不到的繞過。這是為什麼 verifier 必須外部。</li></ul><h2 id="_3-老實的架構診斷-write-path-世界級-read-path-是斷的" tabindex="-1">3. 老實的架構診斷：write path 世界級，read path 是斷的 <a class="header-anchor" href="#_3-老實的架構診斷-write-path-世界級-read-path-是斷的" aria-label="Permalink to &quot;3. 老實的架構診斷：write path 世界級，read path 是斷的&quot;">​</a></h2><p>親驗（非臆測）本 workspace 的閉環底料：</p><table tabindex="0"><thead><tr><th>環節</th><th>現況（收據）</th><th>判定</th></tr></thead><tbody><tr><td>traces 收集</td><td>⚠️<strong>已修正（見 §7.5）</strong>：task-log 有 <code>skills_used</code> <strong>欄位</strong>但值 <strong>0/1014 全空</strong>——生產端沒寫</td><td>❌ write <strong>也是斷的</strong></td></tr><tr><td>lessons 累積</td><td><code>memory/LESSONS.md</code> 101 條 <code>[失敗模式]→[防範]</code></td><td>✅ write 存在</td></tr><tr><td>eval oracle 基建</td><td><code>research/evals/</code>（baseline/coreset/runs/evaluate.py）</td><td>✅ 存在</td></tr><tr><td><strong>traces → dreaming</strong></td><td>dreaming SKILL 明寫「只讀 memory/+research/reports/」<strong>不讀 task-log</strong></td><td>❌ <strong>read 斷</strong></td></tr><tr><td><strong>LESSONS → 動作</strong></td><td>無機制在高風險動作前 surface 相關 lesson（本 session 親證：我重犯 2026-07-04 已記的 lesson）</td><td>❌ <strong>read 斷</strong></td></tr><tr><td>語意檢索</td><td><code>.router-log.jsonl</code> 顯示 <code>embed_stub:true</code>、score 0.0，skill 路由純 BM25</td><td>❌ <strong>read 降級</strong></td></tr></tbody></table><blockquote><p><strong>核心洞見</strong>：你的 workspace <strong>會寫日記（traces + lessons），但不會在動手前翻日記。</strong> 知識被累積、卻沒被 circulate 到 point-of-need。兩個最深的缺口（traces→dreaming、LESSONS→動作）<strong>同形狀</strong>：資料存在，送達使用點的那條邊缺席。而語意檢索基建（embedding）還是 stub。<strong>read path 是系統性的弱側。</strong></p></blockquote><h2 id="_4-閉環-roadmap-skills→loops→traces→dreaming→更好的-skills" tabindex="-1">4. 閉環 roadmap（skills→loops→traces→dreaming→更好的 skills） <a class="header-anchor" href="#_4-閉環-roadmap-skills→loops→traces→dreaming→更好的-skills" aria-label="Permalink to &quot;4. 閉環 roadmap（skills→loops→traces→dreaming→更好的 skills）&quot;">​</a></h2><p>要「完整且有效達成閉環」，唯一真正必要的是補 <strong>read path</strong>：</p><ul><li><strong>#1（最高槓桿）retrieval-at-point-of-need</strong><ul><li><strong>LESSONS → 動作</strong>：高風險動作（改 hook/rule、不可逆操作）前，機械 grep LESSONS 對應 signature 注入提醒。本 session 親證：這一條就能擋下我的 P0#1 bug。</li><li><strong>traces → dreaming</strong>：dreaming 輸入從「人寫的 memory/reports」擴充到「機器記的 task-log outcome/failure_mode」——底料已存在，就差接線。</li><li><strong>修 embed_stub</strong>：讓語意檢索真的跑（skill 路由 + 記憶查詢式選讀，G-Mem）。</li></ul></li><li><strong>#2 external oracle（A5，本 session 血的教訓）</strong>：per-skill eval fixture + dreaming held-out eval。self-authored oracle 有作者形狀的盲點；候選改進須過外部/異模型驗證才算數。</li><li><strong>#3 別加，要 wire/consolidate</strong>：31 skills + 12 疑似重疊 = comprehension debt。fusion/multi-mode 缺的<strong>不是各自的自我進化引擎</strong>（那會犯 Rule-of-3），是 #1#2 的<strong>共享 read-path 電路</strong>——wire 一次全體受益。</li><li><strong>#4 把外部驗證與 retrieval 自動化</strong>：今天 Fable 終審、dreaming、稽核<strong>都要人（你）顯式觸發</strong>。智能體的定義就是這些 read/verify 迴圈<strong>自己會觸發</strong>（離線、外部 oracle、不可逆改動仍人閘）。</li></ul><h2 id="_5-智能體願景的一句話" tabindex="-1">5. 智能體願景的一句話 <a class="header-anchor" href="#_5-智能體願景的一句話" aria-label="Permalink to &quot;5. 智能體願景的一句話&quot;">​</a></h2><blockquote><p>今天這個 workspace 是<strong>一件優秀的樂器</strong>，需要一位熟練的人（你）去彈——你觸發稽核、你叫 Fable 把關、你跑 dreaming。要成為<strong>智能體</strong>，它得長出<strong>自主神經系統</strong>：自己觸發 retrieval、自己觸發對抗驗證、自己蒸餾——用外部 oracle、離線、不可逆處人閘。<strong>器官都在，缺的是讓它們自己動起來的 read 迴圈。</strong></p></blockquote><h2 id="_6-未竟項-誠實-tracked-非宣稱完成" tabindex="-1">6. 未竟項（誠實 tracked，非宣稱完成） <a class="header-anchor" href="#_6-未竟項-誠實-tracked-非宣稱完成" aria-label="Permalink to &quot;6. 未竟項（誠實 tracked，非宣稱完成）&quot;">​</a></h2><p>backlog 剩 P1/P2：#4 unverified_success 僅 commit 時強制（措辭標明）、#5 test-integrity proxy 子集、<strong>#6 [P]/[E] 顆粒度重標（→ 路由 autoload-evolution）</strong>、#8 README byte 公式（cosmetic，defer 避免 desync healthcheck）、#9 RECORD 去重、#10 handoff review-by 過期（需內容 review 非橡皮圖章）、#12 hygiene（ship-review↔autoresearch:ship 重疊 / memory-compactor 未進 RESOLVER / git add -A 無 hook）。概念層新 gap：G-WF/G-Cache/G-Mem/深度裁決池薄。</p><blockquote><p><strong>本報告即 read-path 的一次示範</strong>：它把散落在 12 commit、6 agent 產出、1 次 Fable 對抗稽核裡的教訓，consolidate 成一處可 retrieve 的 insight——這正是 #1 要自動化的東西。</p></blockquote><h2 id="_7-5-update-深挖後修正——第四次「schema-territory」-超越-§3-的-traces-判斷" tabindex="-1">7.5 UPDATE（深挖後修正——第四次「schema≠territory」，超越 §3 的 traces 判斷） <a class="header-anchor" href="#_7-5-update-深挖後修正——第四次「schema-territory」-超越-§3-的-traces-判斷" aria-label="Permalink to &quot;7.5 UPDATE（深挖後修正——第四次「schema≠territory」，超越 §3 的 traces 判斷）&quot;">​</a></h2><p>「把 dreaming 輸入換成機器記的」深挖到生產端，<strong>發現前提不成立</strong>（親驗）：</p><ul><li><strong>task-log 的 <code>skills_used</code> 值 0/1014 全空、<code>failure_mode</code> 0/1014、<code>outcome</code> 858/1014=unknown</strong>。task-log 實為 token/model <strong>帳</strong>（全 <code>backfilled</code>，源 claude-ios/desktop/cli），非 skill-outcome 軌跡。</li><li><strong>消費端早已建好且在空轉</strong>：<code>skill-optimizer.py</code>（「read task-log where skills_used contains this skill」）、<code>skill-crystallizer.py</code>、<code>skill-risk-propagator.py</code>、<code>skill-usage-tracker.py</code> 全讀 <code>skills_used</code>——讀到的永遠是 []。</li><li><strong>行級根因</strong>：<code>session-stop.sh:420</code> 有「Parse transcript for Skill tool_use」——<strong>已算出用了哪些 skill</strong>，但只 bump 各 skill METADATA，<strong>沒寫進它 append 的 task-log 列的 <code>skills_used</code></strong>；<code>backfill-task-log.py:26</code> 亦明填占位 []。<strong>資料被算出、沒 wire 到消費端讀的欄位。</strong></li></ul><h3 id="閉環真正的第一刀-可執行-spec" tabindex="-1">閉環真正的第一刀（可執行 spec） <a class="header-anchor" href="#閉環真正的第一刀-可執行-spec" aria-label="Permalink to &quot;閉環真正的第一刀（可執行 spec）&quot;">​</a></h3><blockquote><p>順序修正：<strong>① 修生產端（trace capture）→ ② 接 dreaming → ③ eval 閘</strong>。①之前，②③無料可用。</p></blockquote><p><strong>Fix：<code>session-stop.sh</code> 的 task-log append 補寫 <code>skills_used</code>（重用同檔既有的 transcript Skill 解析，非新造）</strong></p><ul><li><strong>Done-when</strong>：跑一次帶 Skill 呼叫的 session 後，<code>tail -1 task-log.jsonl</code> 的 <code>skills_used</code> 非空且含實際呼叫的 skill 名。</li><li><strong>Oracle（外部、可 oracle-qualify）</strong>：餵一個合成 transcript（含 2 個已知 Skill tool_use）給 append 邏輯 → 斷言輸出列 <code>skills_used</code>==那 2 個名；餵無 Skill 的 → []。先驗 oracle 抓得出差異再改。</li><li><strong>順帶</strong>：<code>outcome</code> 從 transcript 末狀態/失敗計數推導（session-stop 已數 <code>FAILURE_COUNT</code>，L409）；<code>failure_mode</code> 由失敗工具類型填。</li><li><strong>風險</strong>：session-stop 是 400+ 行背景+lock 關鍵 hook → 外科手術式、oracle-first、改後跑既有 <code>scripts/verify-tasklog.sh</code>。<strong>不可在疲勞 context rush</strong>（本 session P0#1 教訓）。</li></ul><p><em><em>修好這一刀 = 一整排既有 skill-</em> 工具 + dreaming 同時活過來</em>*，閉環的 traces 才真正開始流動。這是「完整且有效達成閉環」的<strong>唯一必要起手式</strong>，其餘皆下游。</p><h2 id="_8-斷点系統性稽核批-2-sweep-→-13-斷点-→-修" tabindex="-1">8. 斷点系統性稽核批（2 sweep → 13 斷点 → 修） <a class="header-anchor" href="#_8-斷点系統性稽核批-2-sweep-→-13-斷点-→-修" aria-label="Permalink to &quot;8. 斷点系統性稽核批（2 sweep → 13 斷点 → 修）&quot;">​</a></h2><p>延伸「read-path 斷」的診斷，2 個 fresh-context sweep（scripts 資料 wiring + hooks 宣稱≠實際，皆抽樣真實資料非讀 schema）掃出 <strong>13 個斷点</strong>，分兩個系統性 pattern：</p><p><strong>Pattern 1 — 假強制（宣稱 enforce 實則 advisory/不可阻斷）</strong>：</p><ul><li><strong>D1</strong>（危，harness 曾出 self-modification 警告）：<code>session-init</code> exit 2 宣稱擋 startup（含反劫持安全檢查），但 SessionStart 平台不可阻斷 → 假防護。<strong>修</strong>：誠實化 + sentinel 真防線（remote-mismatch 寫 sentinel → <code>user-prompt-submit</code>（平台可阻斷）exit 2 擋）；parent no-lockout oracle 過；<strong>Fable frontier 終審中</strong>。</li><li>D2 README matcher 過時 · D5 usage-delegation 恆 advisory（config-gated）· <strong>D4 被查證推翻</strong>（契約本正確，sweep 誤判）。</li></ul><p><strong>Pattern 2 — read-path 斷（資料收集了沒流到用處，同 §3-§7.5 主軸）</strong>：</p><ul><li>B1 skill-optimizer 讀 dry-run 假 audit（16 天 0 真候選）· B3 compress-metrics 漏 63% 資料 · C1/C2/C3 生產孤兒（heartbeat/autoload/command-log 無消費端）· R1 routine B/D/E 不寫 heartbeat（監控盲）。</li></ul><p><strong>方法論收穫（本批血證，補強前文）</strong>：</p><ul><li><strong>schema≠territory 重現 5+ 次</strong>：/goal、task-log skills_used（欄位在值 0/1017 空）、L420 機制、routine「死」（實則 fire 只是不寫 heartbeat）、audit 分數（dry-run 常數）——<strong>每次都是「看 code/schema/heartbeat」誤判、「抽樣真實值/查 trigger」才對</strong>。</li><li><strong>reviewer 檔位 ≥ executor+1（使用者原則）+ 天花板</strong>：sonnet 執行→我 Opus 審（+1 合法）；opus 執行(D1)→只有 Fable(frontier) 夠格審；<strong>frontier 執行(A1)→無更高檔 → 閘落在確定性 oracle（程式非模型，tier-agnostic）+ 異 context</strong>。</li><li><strong>stale-base worktree 回歸</strong>：fresh-context implementer 改「parent 本 session 已編輯的檔」→ pull 覆寫掉 parent 的修（本批 README P0#2 誠實化被 impl-1 worktree 覆寫，diff 審時攔下）→ 並行 worktree 對 parent 已動檔有回歸風險，整合前必逐檔 diff 審。</li></ul><p><strong>A1 收束</strong>：先判「撤」（R5 證 skills_used [] 多為正確、硬改 backfill 競態高風險零收益），後依使用者指示交 <strong>Fable 實作</strong>（修正：對 routine session（allowed_tools 含 Skill）有條件收益；frontier 對檔最高風險改動）。狀態：Fable 實作中，oracle + 異 context 把關。</p><blockquote><p><strong>本批再次示範 read-path 的價值</strong>：13 斷点全靠「主動 sweep + 抽樣真實資料」挖出，而非等它們自己浮現——這正是 §4 roadmap #1「retrieval-at-point-of-need」若自動化後，系統該對自己做的事。</p></blockquote><h2 id="_9-update-2026-07-20-後續-session-親驗-第一刀已落地-首筆真-trace-流動" tabindex="-1">9. UPDATE 2026-07-20（後續 session 親驗）：第一刀已落地，首筆真 trace 流動 <a class="header-anchor" href="#_9-update-2026-07-20-後續-session-親驗-第一刀已落地-首筆真-trace-流動" aria-label="Permalink to &quot;9. UPDATE 2026-07-20（後續 session 親驗）：第一刀已落地，首筆真 trace 流動&quot;">​</a></h2><ul><li><strong>A1 實作完成</strong>（Fable，<code>session-stop.sh:458-563</code>）：skills-only upsert——sid 已存在時只改寫 <code>skills_used</code>（值非空且異於既有才寫，避開 backfill 競態）；來源重用同檔既有的 transcript Skill 解析（<code>skill-usage-tracker.py</code>），非新造。</li><li><strong>活體收據（抽真值非讀 schema）</strong>：<code>evolution/task-log.jsonl</code> 1027 列出現<strong>第一筆非空</strong> <code>skills_used</code>——<code>/teach</code> session（<code>5692f0a0…</code>）記到 <code>[&#39;deep-understanding&#39;]</code>、outcome=success。§7.5 Done-when（帶 Skill 呼叫的 session 後該列 skills_used 非空含實際 skill 名）<strong>達成</strong>。</li><li><strong>歷史 1026 筆 <code>[]</code> 不回填</strong>：依 §8 A1/R5 查證多為正確（該等 session 未用 Skill），硬回填競態高風險零收益。</li><li><strong>下游現況</strong>：traces 開始流動 → 消費端（skill-optimizer/crystallizer/risk-propagator/dreaming）從此有料可讀；②dreaming 接線與 ③eval 閘轉為當前 head，④routine 排程在其後（順序論證 + hook/routine/code 工具判準見 <code>2026-07-20-routine-closure-learning.md</code>）。</li><li><strong>②dreaming 接線完成</strong>（sonnet 執行 + parent 親驗，oracle-first）：<code>consolidate.sh</code> 新增 <code>=== TASK-LOG machine traces ===</code> 節（<code>${TASKLOG_PATH:-evolution/task-log.jsonl}</code> 聚合非空 <code>skills_used</code> × outcome 分布 + failure_mode 對；容錯壞行、無檔/零 trace 明示）；SKILL.md 三處同步（OBSERVE digest 描述、PROPOSE 溯源枚舉加 task-log、安全邊界讀取範圍）。oracle = <code>tests/tasklog-digest-fixture.sh</code>（合成 fixture A 含已知 skills+壞行 / B 全空，pre-impl 先驗 FAIL 再實作）。親跑 4 條 Done-when 全綠：oracle PASS、真實 digest 出現 <code>deep-understanding: 1 次（success=1）</code>、<code>digest OK</code> 無回歸、SKILL.md 3 處引用。<strong>當前 head → ③eval 閘。</strong></li></ul>',39)])])}const u=t(a,[["render",n]]);export{h as __pageData,u as default};
